// src/App.js
import React, { useState, useEffect } from 'react';
import './App.css';

const API_BASE = 'http://localhost:5000/api/user';

// Complete SMS Conversation Flow - User Friendly Steps
const CONVERSATION_STEPS = [
  {
    id: 1,
    title: '📱 Activate Service',
    subtitle: 'Start your dating journey',
    description: 'Send "PENZI" to activate the dating service',
    icon: '💑',
    userAction: 'You send:',
    systemResponse: 'System replies:',
    defaultUserMessage: 'PENZI',
    systemMessage: 'Welcome to our dating service with 6000 potential dating partners! To register SMS start#name#age#gender#county#town to 22141.',
    endpoint: '/activate',
    method: 'POST',
    requiresPhone: false,
    inputType: 'message',
    defaultInput: 'PENZI',
    bodyTemplate: { "message": "{input}" },
    successMessage: '✅ Service activated! You can now register.'
  },
  {
    id: 2,
    title: '📝 Register Profile',
    subtitle: 'Create your dating profile',
    description: 'Provide your basic information',
    icon: '👤',
    userAction: 'You send:',
    systemResponse: 'System replies:',
    defaultUserMessage: 'start#Jamal Jalang\'o#29#Male#Mombasa#Bamburi',
    systemMessage: 'Your profile has been created successfully Jamal. SMS details#levelOfEducation#profession#maritalStatus#religion#ethnicity to 22141.',
    endpoint: '/register',
    method: 'POST',
    requiresPhone: true,
    phoneLabel: 'Your Phone Number',
    defaultPhone: '0712345678',
    inputType: 'sms_format',
    smsFormat: 'start#name#age#gender#county#town',
    fields: [
      { key: 'name', label: 'Full Name', placeholder: 'Jamal Jalang\'o', required: true },
      { key: 'age', label: 'Age', placeholder: '29', type: 'number', required: true },
      { key: 'gender', label: 'Gender', placeholder: 'Male', type: 'select', options: ['Male', 'Female', 'Other'], required: true },
      { key: 'county', label: 'County', placeholder: 'Mombasa', required: true },
      { key: 'town', label: 'Town/City', placeholder: 'Bamburi', required: true }
    ],
    bodyTemplate: { 
      "phone_number": "{phone}",
      "name": "{name}",
      "age": "{age}",
      "gender": "{gender}",
      "county": "{county}",
      "town": "{town}"
    },
    successMessage: '✅ Registration successful! Complete your profile now.'
  },
  {
    id: 3,
    title: '📋 Complete Profile',
    subtitle: 'Add more details about yourself',
    description: 'Share your education, profession, and background',
    icon: '📝',
    userAction: 'You send:',
    systemResponse: 'System replies:',
    defaultUserMessage: 'details#graduate#accountant#single#christian#kisii',
    systemMessage: 'This is the last stage of registration. SMS a brief description of yourself starting with MYSELF.',
    endpoint: '/{phone}/complete-profile',
    method: 'POST',
    requiresPhone: true,
    phoneLabel: 'Your Phone Number',
    defaultPhone: '0712345678',
    inputType: 'form',
    fields: [
      { key: 'education_level', label: 'Education Level', placeholder: 'Graduate', type: 'select', options: ['Primary', 'Secondary', 'Certificate', 'Diploma', 'Graduate', 'Post Graduate'], required: true },
      { key: 'profession', label: 'Profession', placeholder: 'Accountant', required: true },
      { key: 'marital_status', label: 'Marital Status', placeholder: 'Single', type: 'select', options: ['Single', 'Married', 'Divorced', 'Widowed', 'Separated'], required: true },
      { key: 'religion', label: 'Religion', placeholder: 'Christian', required: true },
      { key: 'ethnicity', label: 'Ethnicity/Tribe', placeholder: 'Kisii', required: true }
    ],
    bodyTemplate: {
      "education_level": "{education_level}",
      "profession": "{profession}",
      "marital_status": "{marital_status}",
      "religion": "{religion}",
      "ethnicity": "{ethnicity}"
    },
    successMessage: '✅ Profile completed! Now tell us about yourself.'
  },
  {
    id: 4,
    title: '💬 Describe Yourself',
    subtitle: 'Tell others who you are',
    description: 'Share a brief description of your personality',
    icon: '💭',
    userAction: 'You send:',
    systemResponse: 'System replies:',
    defaultUserMessage: 'MYSELF hardworking, honest, family-oriented, loves nature and adventure',
    systemMessage: 'You are now registered for dating! To search for a MPENZI, SMS match#age#town to 22141.',
    endpoint: '/{phone}/self-description',
    method: 'POST',
    requiresPhone: true,
    phoneLabel: 'Your Phone Number',
    defaultPhone: '0712345678',
    inputType: 'message',
    messagePrefix: 'MYSELF',
    placeholder: 'Describe yourself (e.g., hardworking, honest, family-oriented)',
    defaultInput: 'hardworking, honest, family-oriented, loves nature and adventure',
    bodyTemplate: { "description": "{input}" },
    successMessage: '✅ You are now fully registered! Start matching with others.'
  },
  {
    id: 5,
    title: '🔍 Search Matches',
    subtitle: 'Find your perfect match',
    description: 'Search for matches by age range and location',
    icon: '🔎',
    userAction: 'You send:',
    systemResponse: 'System replies:',
    defaultUserMessage: 'match#26-30#Nairobi',
    systemMessage: 'We have found matches! View them below.',
    endpoint: '/sms',
    method: 'POST',
    requiresPhone: true,
    phoneLabel: 'Your Phone Number',
    defaultPhone: '0712345678',
    inputType: 'sms_format',
    smsFormat: 'match#age_range#town',
    fields: [
      { key: 'age_range', label: 'Age Range', placeholder: '26-30', required: true },
