  },
  {
    id: 12,
    title: '📊 Dashboard',
    subtitle: 'Your dating activity summary',
    description: 'View all your interests and matches',
    icon: '📊',
    userAction: 'You view:',
    systemResponse: 'Your dashboard:',
    endpoint: '/{phone}/my-interests',
    method: 'GET',
