function App() {
  const [currentStep, setCurrentStep] = useState(0);
  const [completedSteps, setCompletedSteps] = useState(new Set());
  const [responseData, setResponseData] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [formData, setFormData] = useState({});
  const [responseStatus, setResponseStatus] = useState(null);
  const [responseMessage, setResponseMessage] = useState('');
  const [isSuccess, setIsSuccess] = useState(false);
  const [history, setHistory] = useState([]);
  const [historyLoaded, setHistoryLoaded] = useState(false);
  const [showHelp, setShowHelp] = useState(false);

  // Load saved state
  useEffect(() => {
    try {
      const savedState = localStorage.getItem('datingAppState');
      if (savedState) {
        const parsed = JSON.parse(savedState);
        setCurrentStep(parsed.currentStep || 0);
        setCompletedSteps(new Set(parsed.completedSteps || []));
        setHistory(parsed.history || []);
        setHistoryLoaded(true);
      }
    } catch (e) {
      console.warn('Could not load saved state:', e);
    }
  }, []);

  // Save state
  useEffect(() => {
    if (!historyLoaded) return;
    try {
      const stateToSave = {
        currentStep,
        completedSteps: Array.from(completedSteps),
        formData,
        history: history.slice(-50)
      };
      localStorage.setItem('datingAppState', JSON.stringify(stateToSave));
    } catch (e) {
      console.warn('Could not save state:', e);
    }
  }, [currentStep, completedSteps, formData, history, historyLoaded]);

  // Initialize form data
  useEffect(() => {
    const step = CONVERSATION_STEPS[currentStep];
    const initialData = {};

    if (step.requiresPhone) {
      initialData.phone = step.defaultPhone || '0712345678';
    }
    if (step.fields) {
      step.fields.forEach(field => {
        initialData[field.key] = '';
      });
    }
    if (step.defaultTarget) {
      initialData.target = step.defaultTarget;
    }
    if (step.defaultInput) {
      initialData.input = step.defaultInput;
    }
    if (step.queryParams) {
      Object.keys(step.queryParams).forEach(key => {
        initialData[`param_${key}`] = step.queryParams[key];
      });
    }

    setFormData(prev => ({ ...prev, ...initialData }));

    // Show saved response
    const savedResponse = history.find(h => h.step === currentStep);
    if (savedResponse) {
      setResponseData(savedResponse.response);
      setResponseStatus(savedResponse.status);
      setResponseMessage(savedResponse.message || '');
      setIsSuccess(savedResponse.success || false);
    } else {
      setResponseData(null);
      setResponseStatus(null);
      setResponseMessage('');
      setIsSuccess(false);
    }
  }, [currentStep, history]);

  const handleInputChange = (field, value) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const buildSmsMessage = (step) => {
    if (!step.fields) return '';

    const parts = [];
    step.fields.forEach(field => {
      const value = formData[field.key] || '';
      if (value) parts.push(value);
    });

    if (step.smsFormat) {
      let message = step.smsFormat;
      step.fields.forEach(field => {
        message = message.replace(`{${field.key}}`, formData[field.key] || '');
      });
      return message;
    }

    return parts.join('#');
  };

  const executeApi = async () => {
    const step = CONVERSATION_STEPS[currentStep];
    setIsLoading(true);
    setResponseStatus(null);
    setResponseMessage('');
    setIsSuccess(false);

    try {
      let endpoint = step.endpoint;
      let phone = formData.phone || step.defaultPhone || '';
      let target = formData.target || step.defaultTarget || '';

      // Replace placeholders
      if (step.requiresPhone) {
        endpoint = endpoint.replace('{phone}', phone);
      }
      if (step.requiresTarget) {
        endpoint = endpoint.replace('{target}', target);
      }

      // Build URL
      let fullUrl = API_BASE + endpoint;

      // Handle query params
      if (step.method === 'GET' && step.queryParams) {
        const params = new URLSearchParams();
        Object.keys(step.queryParams).forEach(key => {
          const value = formData[`param_${key}`] || step.queryParams[key];
          if (value) params.append(key, value);
        });
        const queryString = params.toString();
        if (queryString) {
          fullUrl += '?' + queryString;
        }
      }

      // Build body
      let body = null;
      if (step.bodyTemplate) {
        body = { ...step.bodyTemplate };
        Object.keys(body).forEach(key => {
          let value = body[key];
          // Replace placeholders
          Object.keys(formData).forEach(fieldKey => {
            if (typeof value === 'string') {
              value = value.replace(`{${fieldKey}}`, formData[fieldKey] || '');
            }
          });
          // Handle special case for input
          if (typeof value === 'string' && value.includes('{input}')) {
            value = value.replace('{input}', formData.input || step.defaultInput || '');
          }
          // Handle response
          if (typeof value === 'string' && value.includes('{response}')) {
            value = value.replace('{response}', formData.response || 'accept');
          }
          body[key] = value;
        });
      }

      // Execute request
      const options = {
        method: step.method,
        headers: {
          'Content-Type': 'application/json',
          'Accept': 'application/json'
        }
      };

      if (body && (step.method === 'POST' || step.method === 'PUT')) {
        options.body = JSON.stringify(body);
      }

      const startTime = Date.now();
      const response = await fetch(fullUrl, options);
      const endTime = Date.now();
      const duration = endTime - startTime;

      let responseData;
      const contentType = response.headers.get('content-type');
      if (contentType && contentType.includes('application/json')) {
        responseData = await response.json();
      } else {
        responseData = await response.text();
      }

      const result = {
        status: response.status,
        statusText: response.statusText,
        duration: duration,
        url: fullUrl,
        data: responseData,
        success: response.ok
      };

      setResponseData(result);
      setResponseStatus(response.ok ? 'success' : 'error');

      let successMsg = '';
      if (response.ok && step.successMessage) {
        successMsg = step.successMessage;
        setResponseMessage(successMsg);
        setIsSuccess(true);
      } else if (!response.ok) {
        const errorMsg = responseData?.message || responseData?.error || `Error ${response.status}: ${response.statusText}`;
        setResponseMessage(errorMsg);
        setIsSuccess(false);
      }

      if (response.ok) {
        setCompletedSteps(prev => new Set([...prev, currentStep]));
      }

      saveToHistory(currentStep, result, response.ok ? 'success' : 'error', successMsg, response.ok);

    } catch (error) {
      const errorResult = {
        status: 0,
        statusText: 'Network Error',
        duration: 0,
        url: API_BASE + step.endpoint,
        data: { 
          error: error.message, 
          details: 'Please make sure the server is running at ' + API_BASE 
        },
        success: false
      };
      setResponseData(errorResult);
      setResponseStatus('error');
      setResponseMessage('Network Error: ' + error.message);
      setIsSuccess(false);
      saveToHistory(currentStep, errorResult, 'error', 'Network Error: ' + error.message, false);
    } finally {
      setIsLoading(false);
    }
  };

  const saveToHistory = (step, response, status, message, success) => {
    const entry = {
      step,
      timestamp: new Date().toISOString(),
      response,
      status,
      message,
      success
    };
    setHistory(prev => {
      const filtered = prev.filter(h => h.step !== step);
      return [...filtered, entry];
    });
  };

  const getProgress = () => {
    return Math.round((completedSteps.size / CONVERSATION_STEPS.length) * 100);
  };

  const currentStepData = CONVERSATION_STEPS[currentStep];

  const renderInputForm = () => {
    const step = currentStepData;

    if (step.inputType === 'none') {
      return (
        <div className="input-info">
          <p>ℹ️ No input needed for this step</p>
          <p className="sub-text">Click the button below to continue</p>
        </div>
      );
    }

    if (step.inputType === 'message') {
      const prefix = step.messagePrefix || '';
      return (
        <div className="input-group">
          <label>Your Message</label>
          <div className="message-input-wrapper">
            {prefix && <span className="message-prefix">{prefix}</span>}
            <input
              type="text"
              value={formData.input || ''}
              onChange={(e) => handleInputChange('input', e.target.value)}
              placeholder={step.placeholder || 'Type your message'}
              className="input-field message-input"
            />
          </div>
        </div>
      );
    }

    if (step.inputType === 'sms_format' || step.inputType === 'form') {
      return (
        <div className="input-group form-group">
          <label>Enter Your Details</label>
          {step.fields && step.fields.map((field) => (
            <div key={field.key} className="form-field">
              <label className="field-label">
                {field.label}
                {field.required && <span className="required">*</span>}
              </label>
              {field.type === 'select' ? (
                <select
                  value={formData[field.key] || ''}
                  onChange={(e) => handleInputChange(field.key, e.target.value)}
                  className="input-field"
                >
                  <option value="">Select {field.label}</option>
                  {field.options.map(opt => (
                    <option key={opt} value={opt}>{opt}</option>
                  ))}
                </select>
              ) : (
                <input
                  type={field.type || 'text'}
                  value={formData[field.key] || ''}
                  onChange={(e) => handleInputChange(field.key, e.target.value)}
                  placeholder={field.placeholder}
                  className="input-field"
                />
              )}
            </div>
          ))}
          <div className="sms-preview">
            <strong>Your SMS:</strong> {buildSmsMessage(step) || 'Fill in all fields'}
          </div>
        </div>
      );
    }

    if (step.inputType === 'phone_input') {
      return (
        <div className="input-group">
          <label>{step.targetLabel || 'Phone Number'}</label>
          <input
            type="text"
            value={formData.target || ''}
            onChange={(e) => handleInputChange('target', e.target.value)}
            placeholder="Enter phone number"
            className="input-field"
          />
        </div>
      );
    }

    if (step.inputType === 'response') {
      return (
        <div className="input-group">
          <label>{step.targetLabel || 'Their Phone Number'}</label>
          <input
            type="text"
            value={formData.target || ''}
            onChange={(e) => handleInputChange('target', e.target.value)}
            placeholder="Enter their phone number"
            className="input-field"
          />
          <div className="response-options">
            <label>Your Response</label>
            <div className="response-buttons">
              <button
                className={`response-btn accept ${formData.response === 'accept' ? 'selected' : ''}`}
                onClick={() => handleInputChange('response', 'accept')}
              >
                ✅ Accept
              </button>
              <button
                className={`response-btn reject ${formData.response === 'reject' ? 'selected' : ''}`}
                onClick={() => handleInputChange('response', 'reject')}
              >
                ❌ Decline
              </button>
            </div>
          </div>
        </div>
      );
    }

    return null;
  };

  return (
    <div className="app">
      {/* Header */}
      <header className="header">
        <div className="header-content">
          <h1 className="header-title">
            <span className="header-icon">💑</span>
            PENZI Dating Service
          </h1>
          <p className="header-subtitle">Find your perfect match through SMS</p>
          <div className="header-stats">
            <span className="stat-badge">Step {currentStep + 1} of {CONVERSATION_STEPS.length}</span>
            <span className="stat-badge">✅ {completedSteps.size} Completed</span>
            <span className="stat-badge">{getProgress()}% Done</span>
          </div>
          <div className="progress-bar">
            <div className="progress-fill" style={{ width: `${getProgress()}%` }}></div>
          </div>
        </div>
      </header>

      {/* Main Content */}
      <div className="main-grid">
        {/* Sidebar - Conversation Steps */}
        <aside className="sidebar">
          <h2 className="sidebar-title">📋 Your Journey</h2>
          <div className="step-list">
            {CONVERSATION_STEPS.map((step, index) => {
              const isActive = index === currentStep;
              const isCompleted = completedSteps.has(index);
              const hasHistory = history.some(h => h.step === index);
              return (
                <div
                  key={step.id}
                  onClick={() => setCurrentStep(index)}
                  className={`step-item ${isActive ? 'active' : ''} ${isCompleted ? 'completed' : ''}`}
                >
                  <div className="step-item-content">
                    <span className="step-number">
                      {isCompleted ? '✅' : index + 1}
                    </span>
                    <div className="step-info">
                      <div className="step-title">{step.title}</div>
                      <div className="step-subtitle">{step.subtitle}</div>
                    </div>
                  </div>
                  {hasHistory && !isCompleted && (
                    <span className="step-badge">📝</span>
                  )}
                </div>
              );
            })}
          </div>
        </aside>

        {/* Main Content Area */}
        <main className="main-content">
          <div className="conversation-container">
            {/* Step Header */}
            <div className="step-header">
              <div className="step-icon-wrapper">
                <span className="step-icon">{currentStepData.icon}</span>
              </div>
              <div className="step-header-text">
                <h2>{currentStepData.title}</h2>
                <p>{currentStepData.subtitle}</p>
              </div>
              <span className="step-number-badge">{currentStep + 1}/{CONVERSATION_STEPS.length}</span>
            </div>

            <p className="step-description">{currentStepData.description}</p>

            {/* SMS Conversation Simulation */}
            <div className="sms-simulation">
              <div className="sms-bubble user-message">
                <div className="sms-label">📱 You:</div>
                <div className="sms-content">
                  {currentStepData.inputType === 'none' ? (
                    <span className="sms-placeholder">[No message needed]</span>
                  ) : currentStepData.inputType === 'sms_format' ? (
                    buildSmsMessage(currentStepData) || 'Fill in all fields above'
                  ) : currentStepData.inputType === 'message' ? (
                    formData.input || currentStepData.defaultInput || 'Type your message'
                  ) : currentStepData.inputType === 'phone_input' ? (
                    formData.target || currentStepData.defaultTarget || '[Phone number]'
                  ) : currentStepData.inputType === 'response' ? (
                    formData.response === 'accept' ? 'YES' : formData.response === 'reject' ? 'NO' : '[Choose response]'
                  ) : (
                    'Click execute to continue'
                  )}
                </div>
              </div>

              <div className="sms-bubble system-message">
                <div className="sms-label">🤖 System:</div>
                <div className="sms-content">
                  {currentStepData.systemMessage || 'Processing your request...'}
                </div>
              </div>
            </div>

            {/* Input Form */}
            <div className="input-section">
              {renderInputForm()}

              {/* Action Buttons */}
              <div className="action-buttons">
                <button
                  onClick={() => setCurrentStep(Math.max(0, currentStep - 1))}
                  disabled={currentStep === 0 || isLoading}
                  className="btn btn-secondary"
                >
                  ⬅ Previous
                </button>

                <button
                  onClick={executeApi}
                  disabled={isLoading}
                  className={`btn btn-primary ${isLoading ? 'loading' : ''}`}
                >
                  {isLoading ? '⏳ Sending...' : '📤 Send SMS'}
                </button>

                <button
                  onClick={() => setCurrentStep(Math.min(CONVERSATION_STEPS.length - 1, currentStep + 1))}
                  disabled={currentStep === CONVERSATION_STEPS.length - 1 || isLoading}
                  className="btn btn-secondary"
                >
                  Next ➡
                </button>
              </div>

              {/* Help Button */}
              <button
                className="btn-help"
                onClick={() => setShowHelp(!showHelp)}
              >
                {showHelp ? 'Hide Help ❌' : 'Need Help? ℹ️'}
              </button>

              {showHelp && (
                <div className="help-panel">
                  <h4>💡 How to use this app</h4>
                  <ul>
                    <li>Follow the conversation steps in order</li>
                    <li>Fill in the required information for each step</li>
                    <li>Click "Send SMS" to interact with the system</li>
                    <li>Green checkmarks show completed steps</li>
                    <li>Your progress is automatically saved</li>
                  </ul>
                </div>
              )}
            </div>

            {/* Response Area */}
            <div className="response-area">
              <h3 className="response-title">📤 System Response</h3>

              {responseMessage && (
                <div className={`response-message ${isSuccess ? 'success' : 'error'}`}>
                  <strong>{isSuccess ? '✅ Success:' : '❌ Error:'}</strong> {responseMessage}
                </div>
              )}

              <div className={`response-data ${responseStatus || ''}`}>
                {isLoading ? (
                  <div className="loading-spinner">
                    <div className="spinner"></div>
                    Sending message...
                  </div>
                ) : responseData ? (
                  <pre className="response-json">{JSON.stringify(responseData, null, 2)}</pre>
                ) : (
                  <div className="response-placeholder">
                    💬 System response will appear here after sending your message
                  </div>
                )}
              </div>

              {history.some(h => h.step === currentStep) && (
                <div className="history-indicator">
                  ✅ This step has been completed before
                </div>
              )}
            </div>

            {/* Navigation Help */}
            <div className="navigation-help">
              <span>💡 Use the sidebar to jump to any step</span>
            </div>
          </div>
        </main>
      </div>
    </div>
  );
}

export default App;
